extensibilityCode.react:
// Drawer controlado com direção customizada. A largura sai das custom
// properties --drawer-width / --drawer-max-width (ver Customização), nunca
// de classe de largura: as regras de direção vencem qualquer utilitária.
<Drawer open={open} onOpenChange={setOpen} direction="right">
  <DrawerContent className="painel-filtros">
    {/* conteúdo */}
  </DrawerContent>
</Drawer>

extensibilityCode.vanilla:
// Drawer com direção customizada. Além do gatilho, a gaveta abre e fecha por
// código; fechar por chamada informa o motivo `api`, que separa no analytics a
// gaveta que alguém dispensou da que o programa recolheu.
const gaveta = createDrawer({
  trigger: botaoAbrir,
  direction: 'right',
  content: corpo,
  class: 'painel-filtros',
  onOpenChange: (aberto) => registrarEstado(aberto),
  onClose: (motivo) => registrarSaida(motivo),   // escape | overlay | close-button | api
});

gaveta.open();
gaveta.toggle();
if (gaveta.isOpen()) gaveta.close();

customizationCode.web:
/* Override de véu para tema custom: redeclare o token, não a cor.
   Assim o véu continua sendo um ponto só, e o alfa segue no uso. */
[data-slot='drawer-overlay'] {
  --overlay: 220 40% 10%;
  backdrop-filter: blur(8px);
}

/* Largura do painel lateral: custom property, nunca classe de largura.
   As regras de direção são mais específicas do que qualquer utilitária,
   então uma classe de largura chega ao elemento e não pinta nada. */
.painel-filtros {
  --drawer-width: 90%;
  --drawer-max-width: 28rem;
}

