extensibilityCode.vanilla:
// Drawer with a custom direction. Beyond the trigger, the drawer opens and
// closes by code; closing by call reports the reason `api`, which tells apart in
// analytics the drawer someone dismissed from the one the program put away.
const drawer = createDrawer({
  trigger: openButton,
  direction: 'right',
  content: body,
  class: 'filters-panel',
  onOpenChange: (open) => recordState(open),
  onClose: (reason) => recordExit(reason),   // escape | overlay | close-button | api
});

drawer.open();
drawer.toggle();
if (drawer.isOpen()) drawer.close();

customizationCode.web:
/* Scrim override for a custom theme: redeclare the token, not the colour.
   That keeps the scrim a single point, and the alpha stays at the use site. */
[data-slot='drawer-overlay'] {
  --overlay: 220 40% 10%;
  backdrop-filter: blur(8px);
}

/* Side panel width: custom property, never a width class.
   The direction rules are more specific than any utility, so a width class
   reaches the element and paints nothing. */
.filters-panel {
  --drawer-width: 90%;
  --drawer-max-width: 28rem;
}

